cat > src/main.rs <<'RUST_EOF'
//! Entry point for the reimplementation of the `solar` Solidity compiler CLI.

mod args;
mod errors;
mod help;
mod keccak;
mod output;
mod parser;
mod solidity;
mod zflags;

use std::process::ExitCode;

fn main() -> ExitCode {
    let raw: Vec<String> = std::env::args().collect();
    let prog = args::program_name(&raw);

    // When called without any arguments, clap's default behaviour for a command
    // that requires at least one argument is to print the long help to stderr
    // and exit with code 2.
    if raw.len() <= 1 {
        eprintln!("{}", help::long_help(&prog));
        return ExitCode::from(2);
    }

    match args::parse(&prog, &raw[1..]) {
        Ok(args::ParseOutcome::Help(text)) => {
            print!("{}", text);
            ExitCode::from(0)
        }
        Ok(args::ParseOutcome::Version(text)) => {
            print!("{}", text);
            ExitCode::from(0)
        }
        Ok(args::ParseOutcome::ZHelp(text)) => {
            print!("{}", text);
            ExitCode::from(0)
        }
        Ok(args::ParseOutcome::Run(opts)) => run(opts),
        Err(err) => {
            eprint!("{}", err.render());
            ExitCode::from(err.exit_code())
        }
    }
}

fn run(opts: args::Options) -> ExitCode {
    match crate::output::run(opts) {
        Ok(()) => ExitCode::from(0),
        Err(code) => ExitCode::from(code),
    }
}
