//! Unstable `-Z` flag handling.

/// The help text printed for `-Zhelp` and similar.
pub fn zhelp_text() -> &'static str {
    "error: List of all unstable flags.\n\
     WARNING: these are completely unstable, and may change at any time!\n\
     \n\
     Options:\n\
           -Zui-testing\n\
               Enables UI testing mode\n\
     \n\
           -Ztrack-diagnostics\n\
               Prints a note for every diagnostic that is emitted with the creation and emission location.\n\
               \n\
               This is enabled by default on debug builds.\n\
     \n\
           -Zparse-yul\n\
               Enables parsing Yul files for testing\n\
     \n\
           -Zno-resolve-imports\n\
               Disables import resolution\n\
     \n\
           -Zdump=<KIND[=PATHS...]>\n\
               Print additional information about the compiler's internal state.\n\
               \n\
               Valid kinds are `ast` and `hir`.\n\
     \n\
           -Zast-stats\n\
               Print AST stats\n\
     \n\
           -Zspan-visitor\n\
               Run the span visitor after parsing\n\
     \n\
           -Zprint-max-storage-sizes\n\
               Print contracts' max storage sizes\n\
     \n\
           -Ztypeck\n\
               Type check the program. WIP\n\
     \n\
           -Zhelp\n\
               Print help\n\
     \n\
     Usage: solar [OPTIONS] [INPUT]...\n\
     \n\
     For more information, try '--help'.\n"
