//! Error types produced while parsing CLI arguments and compiling.

#[derive(Debug)]
pub enum CliError {
    /// Argument parsing failed with a clap-style message. Exit code 2.
    Parse(String),
    /// The unstable `-Z` flag parser produced an error that should be
    /// displayed in a `-Zhelp`-style footer. Exit code 2.
    ZParse(String),
}

impl CliError {
    pub fn render(&self) -> String {
        match self {
            CliError::Parse(msg) => msg.clone(),
            CliError::ZParse(msg) => msg.clone(),
        }
    }

    pub fn exit_code(&self) -> u8 {
        match self {
            CliError::Parse(_) | CliError::ZParse(_) => 2,
        }
    }
}
