//! Command-line argument parsing.

use crate::errors::CliError;
use crate::help;
use crate::zflags::{self, ZFlags};

#[derive(Clone, Debug, Default)]
pub struct Options {
    pub threads: usize,
    pub evm_version: String,
    pub stop_after: Option<String>,
    pub out_dir: Option<String>,
    pub emit: Vec<String>,
    pub inputs: Vec<String>,
    pub base_path: Option<String>,
    pub include_paths: Vec<String>,
    pub allow_paths: Vec<String>,
    pub color: String,
    pub verbose: bool,
    pub pretty_json: bool,
    pub pretty_json_err: bool,
    pub error_format: String,
    pub error_format_human: String,
    pub diagnostic_width: Option<u32>,
    pub no_warnings: bool,
    pub zflags: ZFlags,
}

impl Options {
    fn new() -> Self {
        Options {
            threads: help::default_threads(),
            evm_version: "prague".into(),
            stop_after: None,
            out_dir: None,
            emit: Vec::new(),
            inputs: Vec::new(),
            base_path: None,
            include_paths: Vec::new(),
            allow_paths: Vec::new(),
            color: "auto".into(),
            verbose: false,
            pretty_json: false,
            pretty_json_err: false,
            error_format: "human".into(),
            error_format_human: "unicode".into(),
            diagnostic_width: None,
            no_warnings: false,
            zflags: ZFlags::default(),
        }
    }
}

pub enum ParseOutcome {
    Help(String),
    Version(String),
    ZHelp(String),
    Run(Options),
}

pub fn program_name(raw: &[String]) -> String {
    raw.get(0)
        .map(|s| {
            let p = std::path::Path::new(s);
            p.file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| s.clone())
        })
        .unwrap_or_else(|| "solar".into())
}

const EVM_VERSIONS: &[&str] = &[
    "homestead", "tangerineWhistle", "spuriousDragon", "byzantium",
    "constantinople", "petersburg", "istanbul", "berlin", "london",
    "paris", "shanghai", "cancun", "prague", "osaka",
];
const STOP_AFTER: &[&str] = &["parsing", "lowering", "analysis"];
const EMIT: &[&str] = &["abi", "hashes"];
const COLOR: &[&str] = &["auto", "always", "never"];
const ERROR_FORMAT: &[&str] = &["human", "json", "rustc-json"];
const ERROR_FORMAT_HUMAN: &[&str] = &["ascii", "unicode", "short"];

pub fn parse(prog: &str, args: &[String]) -> Result<ParseOutcome, CliError> {
    let mut opts = Options::new();
    let mut i = 0;
    // After `--` all remaining args are positional.
    let mut no_more_flags = false;

    while i < args.len() {
        let a = &args[i];

        if no_more_flags {
            opts.inputs.push(a.clone());
            i += 1;
            continue;
        }

        if a == "--" {
            no_more_flags = true;
            i += 1;
            continue;
        }

        // Long help
        if a == "--help" {
            return Ok(ParseOutcome::Help(help::long_help(prog)));
        }
        if a == "-h" {
            return Ok(ParseOutcome::Help(help::short_help(prog)));
        }
        if a == "--version" {
            return Ok(ParseOutcome::Version(help::long_version().to_string()));
        }
        if a == "-V" {
            return Ok(ParseOutcome::Version(help::short_version().to_string()));
        }

        // -Z flags: may have attached value (-Zname) or separate (-Z name)
        if a == "-Z" {
            let val = args.get(i + 1).cloned().ok_or_else(|| {
                CliError::Parse(clap_error(
                    prog,
                    "a value is required for '-Z <FLAG>' but none was supplied",
                    None,
                ))
            })?;
            i += 2;
            handle_z(&val, &mut opts)?;
            continue;
        }
        if let Some(rest) = a.strip_prefix("-Z") {
            i += 1;
            handle_z(rest, &mut opts)?;
            continue;
        }

        // Helper closure to fetch a value (either "--name=val" already handled
        // or the next argument).
        macro_rules! take_value {
            ($flag:expr) => {{
                if let Some(eq) = a.find('=') {
                    let v = a[eq + 1..].to_string();
                    i += 1;
                    v
                } else {
                    let v = args.get(i + 1).cloned().ok_or_else(|| {
                        CliError::Parse(clap_error(
                            prog,
                            &format!("a value is required for '{}' but none was supplied", $flag),
                            None,
                        ))
                    })?;
                    i += 2;
                    v
                }
            }};
        }

        // --threads / -j / --jobs
        if a == "-j" || a == "--threads" || a == "--jobs"
            || a.starts_with("--threads=") || a.starts_with("--jobs=") || a.starts_with("-j=")
        {
            let val = take_value!("-j, --threads <THREADS>");
            match val.parse::<usize>() {
                Ok(n) => {
                    opts.threads = if n == 0 { num_cpus() } else { n };
                }
                Err(e) => {
                    return Err(CliError::Parse(clap_error(
                        prog,
                        &format!("invalid value '{}' for '--threads <THREADS>': {}", val, e),
                        None,
                    )));
                }
            }
            continue;
        }

        if a == "--evm-version" || a.starts_with("--evm-version=") {
            let val = take_value!("--evm-version <EVM_VERSION>");
            if !EVM_VERSIONS.contains(&val.as_str()) {
                return Err(CliError::Parse(clap_error(
                    prog,
                    &format!("invalid value '{}' for '--evm-version <EVM_VERSION>'", val),
                    Some(&format!("[possible values: {}]", EVM_VERSIONS.join(", "))),
                )));
            }
            opts.evm_version = val;
            continue;
        }

        if a == "--stop-after" || a.starts_with("--stop-after=") {
            let val = take_value!("--stop-after <STOP_AFTER>");
            if !STOP_AFTER.contains(&val.as_str()) {
                return Err(CliError::Parse(clap_error(
                    prog,
                    &format!("invalid value '{}' for '--stop-after <STOP_AFTER>'", val),
                    Some(&format!("[possible values: {}]", STOP_AFTER.join(", "))),
                )));
            }
            opts.stop_after = Some(val);
            continue;
        }

        if a == "--out-dir" || a.starts_with("--out-dir=") {
            let val = take_value!("--out-dir <OUT_DIR>");
            opts.out_dir = Some(val);
            continue;
        }

        if a == "--emit" || a.starts_with("--emit=") {
            let val = take_value!("--emit <EMIT>");
            for part in val.split(',') {
                let part = part.trim();
                if !EMIT.contains(&part) {
                    return Err(CliError::Parse(clap_error(
                        prog,
                        &format!("invalid value '{}' for '--emit <EMIT>'", part),
                        Some(&format!("[possible values: {}]", EMIT.join(", "))),
                    )));
                }
                if !opts.emit.iter().any(|e| e == part) {
                    opts.emit.push(part.to_string());
                }
            }
            continue;
        }

        if a == "--base-path" || a.starts_with("--base-path=") {
            let val = take_value!("--base-path <BASE_PATH>");
            opts.base_path = Some(val);
            continue;
        }

        if a == "-I" || a == "--include-path"
            || a.starts_with("--include-path=") || a.starts_with("-I=")
        {
            let val = take_value!("-I, --include-path <INCLUDE_PATH>");
            opts.include_paths.push(val);
            continue;
        }

        if a == "--allow-paths" || a.starts_with("--allow-paths=") {
            let val = take_value!("--allow-paths <ALLOW_PATHS>");
            opts.allow_paths.push(val);
            continue;
        }

        if a == "--color" || a.starts_with("--color=") {
