//! Minimal Keccak-256 (pre-SHA3) implementation. This is the hash used to
//! compute Solidity function selectors and is the 256-bit variant of Keccak
//! with the original (pre-standardization) padding byte `0x01`.

const ROUND_CONSTANTS: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082,
    0x800000000000808a, 0x8000000080008000,
    0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009,
    0x000000000000008a, 0x0000000000000088,
    0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b,
    0x8000000000008089, 0x8000000000008003,
    0x8000000000008002, 0x8000000000000080,
    0x000000000000800a, 0x800000008000000a,
    0x8000000080008081, 0x8000000000008080,
    0x0000000080000001, 0x8000000080008008,
];

const ROTATION: [[u32; 5]; 5] = [
    [ 0, 36,  3, 41, 18],
    [ 1, 44, 10, 45,  2],
    [62,  6, 43, 15, 61],
    [28, 55, 25, 21, 56],
    [27, 20, 39,  8, 14],
];

fn keccak_f(state: &mut [u64; 25]) {
    for &rc in ROUND_CONSTANTS.iter() {
        // theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }
        for y in 0..5 {
            for x in 0..5 {
                state[x + 5 * y] ^= d[x];
            }
        }

        // rho + pi
        let mut b = [0u64; 25];
        for y in 0..5 {
            for x in 0..5 {
                b[y + 5 * ((2 * x + 3 * y) % 5)] =
                    state[x + 5 * y].rotate_left(ROTATION[x][y]);
            }
        }

        // chi
        for y in 0..5 {
            for x in 0..5 {
                state[x + 5 * y] = b[x + 5 * y]
                    ^ ((!b[(x + 1) % 5 + 5 * y]) & b[(x + 2) % 5 + 5 * y]);
            }
        }

        // iota
        state[0] ^= rc;
    }
}

/// Compute Keccak-256 of the input bytes and return the 32-byte digest.
pub fn keccak256(data: &[u8]) -> [u8; 32] {
    const RATE: usize = 136; // 1088 bits = 136 bytes for Keccak-256
    let mut state = [0u64; 25];
    let mut offset = 0;

    while offset + RATE <= data.len() {
        absorb(&mut state, &data[offset..offset + RATE]);
        keccak_f(&mut state);
        offset += RATE;
    }

    // Padding: pad10*1 with 0x01 delimiter (Keccak pre-SHA3 padding).
    let mut block = [0u8; RATE];
    let rem = data.len() - offset;
    block[..rem].copy_from_slice(&data[offset..]);
    block[rem] = 0x01;
    block[RATE - 1] |= 0x80;
    absorb(&mut state, &block);
    keccak_f(&mut state);

    let mut out = [0u8; 32];
    for i in 0..4 {
        out[i * 8..(i + 1) * 8].copy_from_slice(&state[i].to_le_bytes());
    }
    out
}

fn absorb(state: &mut [u64; 25], block: &[u8]) {
    for (i, chunk) in block.chunks_exact(8).enumerate() {
        let w = u64::from_le_bytes(chunk.try_into().unwrap());
        state[i] ^= w;
    }
}

/// Returns the first `n` bytes of `keccak256(data)` as a lowercase hex string.
pub fn selector_hex(signature: &str) -> String {
    let d = keccak256(signature.as_bytes());
    let mut s = String::with_capacity(8);
    for b in &d[..4] {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_hash() {
        let d = keccak256(b"");
        // Well-known Keccak-256 digest of the empty string.
        let expected = "c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470";
        let got: String = d.iter().map(|b| format!("{:02x}", b)).collect();
        assert_eq!(got, expected);
    }

    #[test]
    fn selector_transfer() {
        assert_eq!(selector_hex("transfer(address,uint256)"), "a9059cbb");
    }
}
