//! A tiny Solidity parser sufficient to extract enough structure from very
//! simple contracts so that we can emit the `abi` and `hashes` output forms
//! supported by the CLI.

use std::fs;
use std::io::Read;
use std::path::Path;

#[derive(Clone, Debug, Default)]
pub struct Source {
    pub label: String,
    pub text: String,
}

pub fn load_input(path: &str) -> Result<Source, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin()
            .read_to_string(&mut s)
            .map_err(|e| format!("failed to read stdin: {}", e))?;
        return Ok(Source { label: "<stdin>".into(), text: s });
    }
    if !Path::new(path).exists() {
        return Err(format!("file {} not found", path));
    }
    let text = fs::read_to_string(path).map_err(|e| format!("{}: {}", path, e))?;
    Ok(Source { label: path.to_string(), text })
}

/// Removes line comments, block comments, and string/character literals to
/// avoid accidentally matching keywords inside them.
pub fn strip_comments(src: &str) -> String {
    let b = src.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == b'/' && i + 1 < b.len() && b[i + 1] == b'/' {
            // line comment
            while i < b.len() && b[i] != b'\n' { i += 1; }
        } else if c == b'/' && i + 1 < b.len() && b[i + 1] == b'*' {
            i += 2;
            while i + 1 < b.len() && !(b[i] == b'*' && b[i + 1] == b'/') { i += 1; }
            if i + 1 < b.len() { i += 2; } else { break; }
        } else if c == b'"' || c == b'\'' {
            let q = c;
            out.push(c);
            i += 1;
            while i < b.len() && b[i] != q {
                if b[i] == b'\\' && i + 1 < b.len() {
                    out.push(b[i]);
                    out.push(b[i + 1]);
                    i += 2;
                } else {
                    out.push(b[i]);
                    i += 1;
                }
            }
            if i < b.len() { out.push(b[i]); i += 1; }
        } else {
            out.push(c);
            i += 1;
        }
    }
    String::from_utf8(out).unwrap_or_default()
}
