//! A small hand-written Solidity parser that recognizes enough structure to
//! produce contract ABIs and function-selector hashes. The parser is
//! intentionally limited - it handles a lexer-level subset of the language.

#[derive(Clone, Debug)]
pub struct Parameter {
    pub name: String,
    pub type_str: String,
    pub indexed: bool,
}

#[derive(Clone, Debug)]
pub struct Function {
    pub name: String,
    pub inputs: Vec<Parameter>,
    pub outputs: Vec<Parameter>,
    pub state_mutability: String, // "pure" | "view" | "nonpayable" | "payable"
    pub is_constructor: bool,
    pub visibility: String,       // "public" | "external" | "internal" | "private" | ""
    pub is_receive: bool,
    pub is_fallback: bool,
}

#[derive(Clone, Debug)]
pub struct Event {
    pub name: String,
    pub inputs: Vec<Parameter>,
    pub anonymous: bool,
}

#[derive(Clone, Debug)]
pub struct StateVar {
    pub name: String,
    pub type_str: String,
    pub visibility: String,
}

#[derive(Clone, Debug, Default)]
pub struct Contract {
    pub name: String,
    pub functions: Vec<Function>,
    pub events: Vec<Event>,
    pub state_vars: Vec<StateVar>,
    pub is_interface: bool,
    pub is_library: bool,
}

/// Tokenizes the source into a vector of `(token, lo)` pairs, dropping
/// whitespace.
fn tokenize(src: &str) -> Vec<(String, usize)> {
    let b = src.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_whitespace() { i += 1; continue; }

        // identifier / keyword / number
        if c.is_ascii_alphabetic() || c == b'_' || c == b'$' {
            let start = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_' || b[i] == b'$') {
                i += 1;
            }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
            continue;
        }
        if c.is_ascii_digit() {
            let start = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'.' || b[i] == b'_') {
                i += 1;
            }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
            continue;
        }
        // string literal
        if c == b'"' || c == b'\'' {
            let q = c;
            let start = i; i += 1;
            while i < b.len() && b[i] != q {
                if b[i] == b'\\' && i + 1 < b.len() { i += 2; } else { i += 1; }
            }
            if i < b.len() { i += 1; }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
