/// Tokenizes the source into a vector of `(token, lo)` pairs, dropping
/// whitespace.
fn tokenize(src: &str) -> Vec<(String, usize)> {
    let b = src.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_whitespace() { i += 1; continue; }

        // identifier / keyword / number
        if c.is_ascii_alphabetic() || c == b'_' || c == b'$' {
            let start = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_' || b[i] == b'$') {
                i += 1;
            }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
            continue;
        }
        if c.is_ascii_digit() {
            let start = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'.' || b[i] == b'_') {
                i += 1;
            }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
            continue;
        }
        // string literal
        if c == b'"' || c == b'\'' {
            let q = c;
            let start = i; i += 1;
            while i < b.len() && b[i] != q {
                if b[i] == b'\\' && i + 1 < b.len() { i += 2; } else { i += 1; }
            }
            if i < b.len() { i += 1; }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
            continue;
        }
