            let q = c;
            let start = i; i += 1;
            while i < b.len() && b[i] != q {
                if b[i] == b'\\' && i + 1 < b.len() { i += 2; } else { i += 1; }
            }
            if i < b.len() { i += 1; }
            out.push((String::from_utf8_lossy(&b[start..i]).into_owned(), start));
            continue;
        }
        // multi-char punctuators are kept as single-char tokens; this is OK
        // because the grammar we recognize only depends on `{`, `}`, `(`, `)`,
        // `[`, `]`, `;`, `,`, `=`, `=>` etc. at top level.
        out.push(((c as char).to_string(), i));
        i += 1;
    }
    out
}

fn find_match(tokens: &[(String, usize)], start: usize, open: &str, close: &str) -> Option<usize> {
    assert_eq!(tokens[start].0, open);
    let mut depth = 0i32;
    for (i, t) in tokens.iter().enumerate().skip(start) {
        if t.0 == open { depth += 1; }
        else if t.0 == close {
            depth -= 1;
            if depth == 0 { return Some(i); }
        }
    }
    None
}

/// Parses the top-level structure of a Solidity source, extracting all
/// contracts/interfaces/libraries and their functions/events/state variables.
pub fn parse(src: &str) -> Vec<Contract> {
    let src = crate::solidity::strip_comments(src);
    let toks = tokenize(&src);

    let mut contracts = Vec::new();
    let mut i = 0;
    while i < toks.len() {
        let t = &toks[i].0;
        if t == "contract" || t == "interface" || t == "library" {
            let is_interface = t == "interface";
            let is_library = t == "library";
            // Next token is the name
            if i + 1 >= toks.len() { break; }
            let name = toks[i + 1].0.clone();
            // Skip until the first `{`
            let mut j = i + 2;
            while j < toks.len() && toks[j].0 != "{" { j += 1; }
            if j >= toks.len() { break; }
            let end = match find_match(&toks, j, "{", "}") {
                Some(e) => e,
                None => break,
            };
            let body = &toks[j + 1..end];
            let contract = parse_contract_body(&name, is_interface, is_library, body);
            contracts.push(contract);
            i = end + 1;
        } else {
            i += 1;
        }
    }
    contracts
}

fn parse_contract_body(
    name: &str,
    is_interface: bool,
    is_library: bool,
    toks: &[(String, usize)],
) -> Contract {
    let mut c = Contract::default();
    c.name = name.to_string();
    c.is_interface = is_interface;
    c.is_library = is_library;

    let mut i = 0;
    while i < toks.len() {
        let t = &toks[i].0;

        // function / constructor / fallback / receive / modifier
        if t == "function" || t == "constructor" || t == "fallback" || t == "receive" {
            let is_ctor = t == "constructor";
            let is_recv = t == "receive";
            let is_fb = t == "fallback";
            // Name is next identifier (unless constructor/fallback/receive which has no name)
            let (fname, name_off) = if is_ctor { ("".to_string(), i + 1) }
                else if is_recv { ("".to_string(), i + 1) }
                else if is_fb { ("".to_string(), i + 1) }
                else {
                    if i + 1 >= toks.len() { break; }
                    (toks[i + 1].0.clone(), i + 2)
                };
            // Now we expect `(`
            let mut j = name_off;
            while j < toks.len() && toks[j].0 != "(" { j += 1; }
            if j >= toks.len() { break; }
            let paren_close = match find_match(toks, j, "(", ")") {
                Some(e) => e,
                None => break,
            };
            let params = parse_params(&toks[j + 1..paren_close]);

            // Parse modifiers and optional returns until `{` or `;`
            let mut k = paren_close + 1;
            let mut state_mut = String::new();
            let mut visibility = String::new();
            let mut outputs: Vec<Parameter> = Vec::new();
            while k < toks.len() && toks[k].0 != "{" && toks[k].0 != ";" {
                let kw = &toks[k].0;
                match kw.as_str() {
                    "pure" | "view" | "payable" => {
                        state_mut = kw.clone();
                        k += 1;
                    }
                    "public" | "external" | "internal" | "private" => {
                        visibility = kw.clone();
                        k += 1;
                    }
                    "returns" => {
                        // Expect `(` next
                        if k + 1 < toks.len() && toks[k + 1].0 == "(" {
                            let close = find_match(toks, k + 1, "(", ")").unwrap_or(toks.len() - 1);
                            outputs = parse_params(&toks[k + 2..close]);
                            k = close + 1;
                        } else {
                            k += 1;
                        }
                    }
                    "virtual" | "override" => {
                        k += 1;
                        // override may have `(...)`
                        if k < toks.len() && toks[k].0 == "(" {
                            let close = find_match(toks, k, "(", ")").unwrap_or(toks.len() - 1);
                            k = close + 1;
                        }
                    }
                    _ => {
                        // Custom modifier, possibly with (...)
                        k += 1;
                        if k < toks.len() && toks[k].0 == "(" {
                            let close = find_match(toks, k, "(", ")").unwrap_or(toks.len() - 1);
                            k = close + 1;
                        }
                    }
                }
            }

            // Skip body if `{ ... }`
            let after = if k < toks.len() && toks[k].0 == "{" {
                let close = find_match(toks, k, "{", "}").unwrap_or(toks.len() - 1);
                close + 1
            } else if k < toks.len() && toks[k].0 == ";" { k + 1 } else { k };

            // Only record functions relevant to ABI.
            if state_mut.is_empty() {
                state_mut = if is_recv || is_fb && visibility == "payable" {
                    "payable".into()
                } else { "nonpayable".into() };
            }

            if !is_fb && !is_recv {
                c.functions.push(Function {
                    name: fname,
                    inputs: params,
                    outputs,
                    state_mutability: state_mut,
                    is_constructor: is_ctor,
                    visibility,
                    is_receive: false,
                    is_fallback: false,
                });
            } else {
                c.functions.push(Function {
                    name: String::new(),
                    inputs: Vec::new(),
                    outputs: Vec::new(),
                    state_mutability: state_mut,
                    is_constructor: false,
                    visibility,
                    is_receive: is_recv,
                    is_fallback: is_fb,
                });
            }

            i = after;
            continue;
        }

        if t == "event" {
            if i + 1 >= toks.len() { break; }
            let ename = toks[i + 1].0.clone();
            let mut j = i + 2;
            while j < toks.len() && toks[j].0 != "(" { j += 1; }
            if j >= toks.len() { break; }
            let close = find_match(toks, j, "(", ")").unwrap_or(toks.len() - 1);
            let params = parse_params(&toks[j + 1..close]);
            // anonymous?
            let mut k = close + 1;
            let mut anonymous = false;
            while k < toks.len() && toks[k].0 != ";" {
                if toks[k].0 == "anonymous" { anonymous = true; }
                k += 1;
            }
            c.events.push(Event { name: ename, inputs: params, anonymous });
            i = if k < toks.len() { k + 1 } else { k };
            continue;
        }

        // Heuristic: scan a simple declaration that ends at `;` at top level
        // of the contract body. If we find a `public` keyword in a storage
        // variable declaration, promote to a getter.
        // (Falls through if unrecognized.)
        if let Some(semi) = find_top_semi(toks, i) {
            if let Some(sv) = parse_state_var(&toks[i..semi]) {
                c.state_vars.push(sv);
            }
            i = semi + 1;
            continue;
        }

        i += 1;
    }
    c
}

fn find_top_semi(toks: &[(String, usize)], start: usize) -> Option<usize> {
    let mut i = start;
    let mut depth_paren = 0i32;
    let mut depth_brace = 0i32;
    let mut depth_bracket = 0i32;
    while i < toks.len() {
        match toks[i].0.as_str() {
            "(" => depth_paren += 1,
            ")" => depth_paren -= 1,
            "{" => depth_brace += 1,
            "}" => depth_brace -= 1,
            "[" => depth_bracket += 1,
            "]" => depth_bracket -= 1,
            ";" if depth_paren == 0 && depth_brace == 0 && depth_bracket == 0 => return Some(i),
            _ => {}
        }
        i += 1;
    }
    None
}

fn parse_state_var(toks: &[(String, usize)]) -> Option<StateVar> {
    // Extract a possibly array-suffixed type (first identifier chain + [] wraps)
    // followed by visibility keyword and the name.
    if toks.is_empty() { return None; }
    let mut i = 0;
    // Parse type
    let mut ty = parse_type(toks, &mut i)?;

    let mut visibility = String::new();
    let mut name: Option<String> = None;
    while i < toks.len() {
        let t = toks[i].0.as_str();
        match t {
            "public" | "external" | "internal" | "private" => {
                visibility = t.to_string();
                i += 1;
            }
            "constant" | "immutable" | "override" | "transient" => {
                i += 1;
                if t == "override" && i < toks.len() && toks[i].0 == "(" {
                    let close = find_match(toks, i, "(", ")").unwrap_or(toks.len() - 1);
                    i = close + 1;
                }
            }
            "=" => break,
            _ if is_ident_tok(&toks[i].0) => {
                name = Some(toks[i].0.clone());
                i += 1;
            }
            _ => { i += 1; }
        }
    }
    // Must have a public visibility to matter to the ABI.
    let name = name?;
    // Trim trailing modifiers from the type
    let _ = &mut ty;
    Some(StateVar { name, type_str: ty, visibility })
}

fn is_ident_tok(s: &str) -> bool {
    let b = s.as_bytes();
    if b.is_empty() { return false; }
    (b[0].is_ascii_alphabetic() || b[0] == b'_' || b[0] == b'$')
        && b.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'_' || *c == b'$')
}

fn is_type_keyword(s: &str) -> bool {
    matches!(s, "address" | "bool" | "string" | "bytes" | "mapping")
        || s.starts_with("uint")
        || s.starts_with("int")
        || s.starts_with("bytes")
        || is_ident_tok(s)
}

fn parse_type(toks: &[(String, usize)], i: &mut usize) -> Option<String> {
    if *i >= toks.len() { return None; }
    let mut ty = toks[*i].0.clone();
    if !is_type_keyword(&ty) { return None; }
    *i += 1;
    // `address payable` is a type
    if ty == "address" && *i < toks.len() && toks[*i].0 == "payable" {
        *i += 1;
    }
    // mapping(K => V) etc.
    if ty == "mapping" && *i < toks.len() && toks[*i].0 == "(" {
        let close = find_match(toks, *i, "(", ")").unwrap_or(toks.len() - 1);
        // Rebuild text roughly
        let inner: Vec<&str> = toks[*i + 1..close].iter().map(|t| t.0.as_str()).collect();
        ty = format!("mapping({})", inner.join(" "));
        *i = close + 1;
    }
    // Trailing array suffixes
    while *i < toks.len() && toks[*i].0 == "[" {
        let close = find_match(toks, *i, "[", "]").unwrap_or(toks.len() - 1);
        let inner: String = toks[*i + 1..close].iter().map(|t| t.0.as_str()).collect::<Vec<_>>().join("");
        ty = format!("{}[{}]", ty, inner);
        *i = close + 1;
    }
    Some(ty)
}

/// Parses the parameter list between parentheses. Each parameter is of the
/// form: `type [storage-location] [indexed] [name]`.
fn parse_params(toks: &[(String, usize)]) -> Vec<Parameter> {
    // Split on top-level commas
    let mut params = Vec::new();
    let mut start = 0usize;
    let mut depth_paren = 0i32;
    let mut depth_bracket = 0i32;
    for i in 0..=toks.len() {
        let at_end = i == toks.len();
        let is_comma = !at_end && toks[i].0 == "," && depth_paren == 0 && depth_bracket == 0;
        if !at_end {
            match toks[i].0.as_str() {
                "(" => depth_paren += 1,
                ")" => depth_paren -= 1,
                "[" => depth_bracket += 1,
                "]" => depth_bracket -= 1,
                _ => {}
            }
        }
        if is_comma || at_end {
            if start < i {
                if let Some(p) = parse_single_param(&toks[start..i]) {
                    params.push(p);
                }
            }
            start = i + 1;
        }
    }
    params
}

fn parse_single_param(toks: &[(String, usize)]) -> Option<Parameter> {
    if toks.is_empty() { return None; }
    let mut i = 0;
    let ty = parse_type(toks, &mut i)?;
    let mut indexed = false;
    let mut name = String::new();
    while i < toks.len() {
        let t = toks[i].0.as_str();
        match t {
            "memory" | "calldata" | "storage" => { i += 1; }
            "indexed" => { indexed = true; i += 1; }
            _ if is_ident_tok(t) => { name = t.to_string(); i += 1; }
            _ => { i += 1; }
        }
    }
    Some(Parameter { name, type_str: ty, indexed })
}
