//! Produces the JSON output for `--emit abi` and `--emit hashes`.

use crate::args::Options;
use crate::keccak::selector_hex;
use crate::parser::{Contract, Function, Parameter};
use crate::solidity::load_input;

pub fn run(opts: Options) -> Result<(), u8> {
    // No inputs at all: "no files found" error.
    if opts.inputs.is_empty() {
        eprintln!("error: no files found");
        eprintln!("  │");
        eprintln!("  ╰ note: if you wish to use the standard input, please specify `-` explicitly");
        eprintln!();
        eprintln!("error: aborting due to 1 previous error");
        eprintln!();
        return Err(1);
    }

    // Read and parse each input. Import-remapping style args like
    // "prefix=path" are ignored - we only record actual source inputs.
    let mut sources: Vec<(String, Vec<Contract>)> = Vec::new();
    let mut had_error = false;
    for inp in &opts.inputs {
        if is_remapping(inp) { continue; }
        match load_input(inp) {
            Ok(src) => {
                let contracts = crate::parser::parse(&src.text);
                sources.push((src.label, contracts));
            }
            Err(msg) => {
                had_error = true;
                eprintln!("error: {}", msg);
                eprintln!();
            }
        }
    }

    if had_error {
        eprintln!("error: aborting due to 1 previous error");
        eprintln!();
        return Err(1);
    }

    if opts.emit.is_empty() {
        // Nothing to emit on success.
        return Ok(());
    }

    emit_json(&opts, &sources);
    Ok(())
}

fn is_remapping(s: &str) -> bool {
    // `prefix=path` with prefix not a path separator
    if let Some(eq) = s.find('=') {
        let pre = &s[..eq];
        if !pre.is_empty() && !pre.contains('/') && !pre.contains('\\') && !pre.ends_with(".sol") {
            return true;
        }
    }
    false
}

fn emit_json(opts: &Options, sources: &[(String, Vec<Contract>)]) {
    use crate::json::*;
    let mut root = JObject::new();
    let mut contracts_obj = JObject::new();

    for (file, contracts) in sources {
        for c in contracts {
            let mut co = JObject::new();
            if opts.emit.iter().any(|e| e == "abi") {
                co.push("abi", JValue::Array(abi_json(c)));
            }
            if opts.emit.iter().any(|e| e == "hashes") {
                let mut ho = JObject::new();
                for sig in function_signatures(c) {
                    let sel = selector_hex(&sig);
                    ho.push(&sig, JValue::String(sel));
                }
                co.push("hashes", JValue::Object(ho));
            }
            let key = format!("{}:{}", file, c.name);
            contracts_obj.push(&key, JValue::Object(co));
        }
    }
    root.push("contracts", JValue::Object(contracts_obj));
    root.push("version", JValue::String("0.1.8".to_string()));

    if opts.pretty_json {
        println!("{}", root.render(true));
    } else {
        // Original emits compact JSON without a trailing newline.
        print!("{}", root.render(false));
    }
}

fn is_reserved_selector_target(f: &Function) -> bool {
    f.is_constructor || f.is_fallback || f.is_receive
}

fn has_public_interface(f: &Function) -> bool {
    !is_reserved_selector_target(f)
        && (f.visibility == "public" || f.visibility == "external")
}

fn function_signatures(c: &Contract) -> Vec<String> {
    // Only functions that are externally visible appear in ABIs and hashes.
    let mut out = Vec::new();
    // Public functions (including interface ones default to external)
    let default_visible = c.is_interface;
    let mut entries: Vec<&Function> = Vec::new();
    for f in &c.functions {
        if is_reserved_selector_target(f) { continue; }
        if has_public_interface(f) || (default_visible && f.visibility.is_empty()) {
            entries.push(f);
        }
    }
    // Public state vars produce getters.
    let mut getters: Vec<(String, String)> = Vec::new();
    for s in &c.state_vars {
        if s.visibility == "public" {
            getters.push((s.name.clone(), s.type_str.clone()));
        }
    }
    // Sort alphabetically (getter names are just the variable names).
    let mut all: Vec<(String, Vec<String>)> = Vec::new();
    for f in entries {
        let types: Vec<String> = f.inputs.iter().map(|p| p.type_str.clone()).collect();
        all.push((f.name.clone(), types));
    }
    for (n, _) in &getters {
        all.push((n.clone(), vec![]));
    }
    all.sort_by(|a, b| a.0.cmp(&b.0));
    for (n, tys) in all {
        out.push(format!("{}({})", n, tys.join(",")));
    }
    out
}

fn abi_json(c: &Contract) -> Vec<crate::json::JValue> {
    use crate::json::*;
    let mut items: Vec<JValue> = Vec::new();

    // Constructor first (only one)
    for f in &c.functions {
        if f.is_constructor {
            let mut o = JObject::new();
            o.push("type", JValue::String("constructor".into()));
            o.push("inputs", JValue::Array(params_json(&f.inputs, false)));
            o.push("stateMutability", JValue::String(f.state_mutability.clone()));
            items.push(JValue::Object(o));
        }
    }
    // Events (stable order: original order)
    for e in &c.events {
        let mut o = JObject::new();
        o.push("type", JValue::String("event".into()));
        o.push("name", JValue::String(e.name.clone()));
        o.push("inputs", JValue::Array(params_json(&e.inputs, true)));
        o.push("anonymous", JValue::Bool(e.anonymous));
        items.push(JValue::Object(o));
    }
    // Functions + state var getters, alphabetically
    #[derive(Clone)]
    enum Entry {
        Func(Function),
        Getter(String, String),
        Fallback(String),
        Receive(String),
    }
    let mut entries: Vec<Entry> = Vec::new();
    for f in &c.functions {
        if f.is_constructor { continue; }
        if f.is_fallback {
            entries.push(Entry::Fallback(f.state_mutability.clone()));
            continue;
        }
        if f.is_receive {
            entries.push(Entry::Receive("payable".into()));
            continue;
        }
        if f.visibility == "public" || f.visibility == "external"
            || (c.is_interface && f.visibility.is_empty())
        {
            entries.push(Entry::Func(f.clone()));
        }
    }
    for sv in &c.state_vars {
        if sv.visibility == "public" {
            entries.push(Entry::Getter(sv.name.clone(), sv.type_str.clone()));
        }
    }
    entries.sort_by(|a, b| key_name(a).cmp(&key_name(b)));

    for e in entries {
        match e {
            Entry::Func(f) => {
                let mut o = JObject::new();
                o.push("type", JValue::String("function".into()));
                o.push("name", JValue::String(f.name.clone()));
                o.push("inputs", JValue::Array(params_json(&f.inputs, false)));
                o.push("outputs", JValue::Array(params_json(&f.outputs, false)));
                o.push("stateMutability", JValue::String(f.state_mutability.clone()));
                items.push(JValue::Object(o));
            }
            Entry::Getter(name, ty) => {
                let mut o = JObject::new();
                o.push("type", JValue::String("function".into()));
                o.push("name", JValue::String(name));
                o.push("inputs", JValue::Array(vec![]));
                let mut out = JObject::new();
                out.push("name", JValue::String("".into()));
                out.push("type", JValue::String(ty.clone()));
                out.push("internalType", JValue::String(ty));
                o.push("outputs", JValue::Array(vec![JValue::Object(out)]));
                o.push("stateMutability", JValue::String("view".into()));
                items.push(JValue::Object(o));
            }
            Entry::Fallback(sm) => {
                let mut o = JObject::new();
                o.push("type", JValue::String("fallback".into()));
                o.push("stateMutability", JValue::String(sm));
                items.push(JValue::Object(o));
            }
            Entry::Receive(sm) => {
                let mut o = JObject::new();
                o.push("type", JValue::String("receive".into()));
                o.push("stateMutability", JValue::String(sm));
                items.push(JValue::Object(o));
            }
        }
    }
    items
}

fn key_name(e: &impl EntryKey) -> String { e.key() }
trait EntryKey { fn key(&self) -> String; }
impl EntryKey for Function { fn key(&self) -> String { self.name.clone() } }

// Implement EntryKey for the local enum via a small adapter.
// (We use an impl block below on the enum via a newtype-less dispatch.)
impl EntryKey for Parameter { fn key(&self) -> String { self.name.clone() } }

// Since EntryKey is small, define a manual impl for the private Entry enum by
// reusing the pattern inline.
mod private_entry_impl {
    use super::{EntryKey};
    impl EntryKey for super::Entry {
        fn key(&self) -> String {
            match self {
                super::Entry::Func(f) => f.name.clone(),
                super::Entry::Getter(n, _) => n.clone(),
                super::Entry::Fallback(_) => "~fallback~".into(),
                super::Entry::Receive(_) => "~receive~".into(),
            }
        }
    }
}

#[derive(Clone)]
enum Entry {
    Func(Function),
    Getter(String, String),
    Fallback(String),
    Receive(String),
}

fn params_json(params: &[Parameter], include_indexed: bool) -> Vec<crate::json::JValue> {
    use crate::json::*;
    params
        .iter()
        .map(|p| {
            let mut o = JObject::new();
            o.push("name", JValue::String(p.name.clone()));
            o.push("type", JValue::String(p.type_str.clone()));
            if include_indexed {
                o.push("indexed", JValue::Bool(p.indexed));
            }
            o.push("internalType", JValue::String(p.type_str.clone()));
            JValue::Object(o)
        })
        .collect()
}
