        eprintln!("  │");
        eprintln!("  ╰ note: if you wish to use the standard input, please specify `-` explicitly");
        eprintln!();
        eprintln!("error: aborting due to 1 previous error");
        eprintln!();
        return Err(1);
    }

    // Read and parse each input. Import-remapping style args like
    // "prefix=path" are ignored - we only record actual source inputs.
    let mut sources: Vec<(String, Vec<Contract>)> = Vec::new();
    let mut had_error = false;
    for inp in &opts.inputs {
        if is_remapping(inp) { continue; }
        match load_input(inp) {
            Ok(src) => {
                let contracts = crate::parser::parse(&src.text);
                sources.push((src.label, contracts));
            }
            Err(msg) => {
                had_error = true;
                eprintln!("error: {}", msg);
                eprintln!();
            }
        }
    }

    if had_error {
        eprintln!("error: aborting due to 1 previous error");
        eprintln!();
        return Err(1);
    }

