//! Very small JSON writer used for `--emit` output. The renderer supports
//! two modes: compact (no whitespace) and pretty (2-space indent, matching
//! the original tool's layout).

#[derive(Clone, Debug)]
pub enum JValue {
    String(String),
    Bool(bool),
    Array(Vec<JValue>),
    Object(JObject),
}

#[derive(Clone, Debug, Default)]
pub struct JObject {
    entries: Vec<(String, JValue)>,
}

impl JObject {
    pub fn new() -> Self { Self::default() }
    pub fn push(&mut self, key: &str, value: JValue) {
        self.entries.push((key.to_string(), value));
    }

    pub fn render(&self, pretty: bool) -> String {
        let mut out = String::new();
        render_object(self, pretty, 0, &mut out);
        out
    }
}

fn escape(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            '\x08' => r.push_str("\\b"),
            '\x0c' => r.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                r.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

fn indent(level: usize, out: &mut String) {
    for _ in 0..level { out.push_str("  "); }
}

fn render_value(v: &JValue, pretty: bool, level: usize, out: &mut String) {
    match v {
        JValue::String(s) => out.push_str(&escape(s)),
        JValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JValue::Array(arr) => render_array(arr, pretty, level, out),
        JValue::Object(o) => render_object(o, pretty, level, out),
    }
}

fn render_array(arr: &[JValue], pretty: bool, level: usize, out: &mut String) {
    if arr.is_empty() { out.push_str("[]"); return; }
    out.push('[');
    if pretty { out.push('\n'); }
    for (i, v) in arr.iter().enumerate() {
        if pretty { indent(level + 1, out); }
        render_value(v, pretty, level + 1, out);
        if i + 1 < arr.len() { out.push(','); }
        if pretty { out.push('\n'); }
    }
    if pretty { indent(level, out); }
    out.push(']');
}

fn render_object(o: &JObject, pretty: bool, level: usize, out: &mut String) {
    if o.entries.is_empty() { out.push_str("{}"); return; }
    out.push('{');
    if pretty { out.push('\n'); }
    for (i, (k, v)) in o.entries.iter().enumerate() {
        if pretty { indent(level + 1, out); }
        out.push_str(&escape(k));
        out.push(':');
        if pretty { out.push(' '); }
        render_value(v, pretty, level + 1, out);
        if i + 1 < o.entries.len() { out.push(','); }
        if pretty { out.push('\n'); }
    }
    if pretty { indent(level, out); }
    out.push('}');
}
