          Run the span visitor after parsing

      -Zprint-max-storage-sizes
          Print contracts' max storage sizes

      -Ztypeck
          Type check the program. WIP

      -Zhelp
          Print help

Usage: solar [OPTIONS] [INPUT]...

For more information, try '--help'.
"
}

/// Kinds of `-Z` flags we recognize. Unknown flags produce an error.
#[derive(Clone, Debug, Default)]
pub struct ZFlags {
    pub help: bool,
    pub ui_testing: bool,
    pub track_diagnostics: bool,
    pub parse_yul: bool,
    pub no_resolve_imports: bool,
    pub ast_stats: bool,
    pub span_visitor: bool,
    pub print_max_storage_sizes: bool,
    pub typeck: bool,
    pub dump: Option<String>,
}

/// Parses a single `-Z` flag value (without the `-Z` prefix).
pub fn parse(z: &mut ZFlags, val: &str) -> Result<(), String> {
    let (name, value) = match val.find('=') {
        Some(eq) => (&val[..eq], Some(&val[eq + 1..])),
        None => (val, None),
    };
    match name {
        "help" => {
            if value.is_some() { return Err(format!(" unexpected value for '-Z{}'", name)); }
            z.help = true;
        }
        "ui-testing" => { z.ui_testing = true; }
        "track-diagnostics" => { z.track_diagnostics = true; }
        "parse-yul" => { z.parse_yul = true; }
        "no-resolve-imports" => { z.no_resolve_imports = true; }
        "ast-stats" => { z.ast_stats = true; }
        "span-visitor" => { z.span_visitor = true; }
        "print-max-storage-sizes" => { z.print_max_storage_sizes = true; }
        "typeck" => { z.typeck = true; }
        "dump" => {
            let v = value.ok_or_else(|| " equal sign is needed when assigning values to '-Zdump=<KIND[=PATHS...]>'".to_string())?;
            let kind = v.split('=').next().unwrap_or("");
            if kind != "ast" && kind != "hir" {
                return Err(format!(
                    " invalid value '{}' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found",
                    v
                ));
            }
            z.dump = Some(v.to_string());
        }
        _ => {
            return Err(format!(" unexpected argument '-Z{}' found", val));
        }
    }
    Ok(())
}
