//! Command-line argument parsing.

use crate::errors::CliError;
use crate::help;
use crate::zflags::{self, ZFlags};

#[derive(Clone, Debug, Default)]
pub struct Options {
    pub threads: usize,
    pub evm_version: String,
    pub stop_after: Option<String>,
    pub out_dir: Option<String>,
    pub emit: Vec<String>,
    pub inputs: Vec<String>,
    pub base_path: Option<String>,
    pub include_paths: Vec<String>,
    pub allow_paths: Vec<String>,
    pub color: String,
    pub verbose: bool,
    pub pretty_json: bool,
    pub pretty_json_err: bool,
    pub error_format: String,
    pub error_format_human: String,
    pub diagnostic_width: Option<u32>,
    pub no_warnings: bool,
    pub zflags: ZFlags,
}

impl Options {
    fn new() -> Self {
        Options {
            threads: help::default_threads(),
            evm_version: "prague".into(),
            stop_after: None,
            out_dir: None,
            emit: Vec::new(),
            inputs: Vec::new(),
            base_path: None,
            include_paths: Vec::new(),
            allow_paths: Vec::new(),
            color: "auto".into(),
            verbose: false,
            pretty_json: false,
            pretty_json_err: false,
            error_format: "human".into(),
            error_format_human: "unicode".into(),
            diagnostic_width: None,
            no_warnings: false,
            zflags: ZFlags::default(),
        }
    }
}

pub enum ParseOutcome {
    Help(String),
    Version(String),
    ZHelp(String),
    Run(Options),
}

pub fn program_name(raw: &[String]) -> String {
    raw.get(0)
        .map(|s| {
            let p = std::path::Path::new(s);
            p.file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| s.clone())
        })
        .unwrap_or_else(|| "solar".into())
}

const EVM_VERSIONS: &[&str] = &[
    "homestead", "tangerineWhistle", "spuriousDragon", "byzantium",
    "constantinople", "petersburg", "istanbul", "berlin", "london",
    "paris", "shanghai", "cancun", "prague", "osaka",
];
const STOP_AFTER: &[&str] = &["parsing", "lowering", "analysis"];
const EMIT: &[&str] = &["abi", "hashes"];
const COLOR: &[&str] = &["auto", "always", "never"];
const ERROR_FORMAT: &[&str] = &["human", "json", "rustc-json"];
const ERROR_FORMAT_HUMAN: &[&str] = &["ascii", "unicode", "short"];

/// Describes a command-line flag for error messages.
struct FlagSpec {
    name: &'static str,
    value_name: &'static str,
    possible: Option<&'static [&'static str]>,
}

impl FlagSpec {
    /// Builds the "missing value" error message matching clap's format.
    fn missing_value_error(&self) -> String {
        let mut s = String::new();
        s.push_str(&format!(
            "error: a value is required for '{} <{}>' but none was supplied\n",
            self.name, self.value_name
        ));
        if let Some(vals) = self.possible {
            s.push_str(&format!("  [possible values: {}]\n", vals.join(", ")));
        }
        s.push_str("\nFor more information, try '--help'.\n");
        s
    }

    /// Builds the "invalid value" error message matching clap's format.
    fn invalid_value_error(&self, got: &str, parse_err: Option<&str>) -> String {
        let mut s = String::new();
        if let Some(e) = parse_err {
            s.push_str(&format!(
                "error: invalid value '{}' for '{} <{}>': {}\n",
                got, self.name, self.value_name, e
            ));
        } else {
            s.push_str(&format!(
                "error: invalid value '{}' for '{} <{}>'\n",
                got, self.name, self.value_name
            ));
        }
        if let Some(vals) = self.possible {
            s.push_str(&format!("  [possible values: {}]\n", vals.join(", ")));
        }
        s.push_str("\nFor more information, try '--help'.\n");
        s
    }
}

const F_THREADS:  FlagSpec = FlagSpec { name: "-j, --threads", value_name: "THREADS", possible: None };
const F_EVM:      FlagSpec = FlagSpec { name: "--evm-version", value_name: "EVM_VERSION", possible: Some(EVM_VERSIONS) };
const F_STOP:     FlagSpec = FlagSpec { name: "--stop-after", value_name: "STOP_AFTER", possible: Some(STOP_AFTER) };
const F_OUTDIR:   FlagSpec = FlagSpec { name: "--out-dir", value_name: "OUT_DIR", possible: None };
const F_EMIT:     FlagSpec = FlagSpec { name: "--emit", value_name: "EMIT", possible: Some(EMIT) };
const F_BASE:     FlagSpec = FlagSpec { name: "--base-path", value_name: "BASE_PATH", possible: None };
const F_INCLUDE:  FlagSpec = FlagSpec { name: "--include-path", value_name: "INCLUDE_PATH", possible: None };
const F_ALLOW:    FlagSpec = FlagSpec { name: "--allow-paths", value_name: "ALLOW_PATHS", possible: None };
const F_COLOR:    FlagSpec = FlagSpec { name: "--color", value_name: "COLOR", possible: Some(COLOR) };
const F_ERRF:     FlagSpec = FlagSpec { name: "--error-format", value_name: "ERROR_FORMAT", possible: Some(ERROR_FORMAT) };
const F_ERRH:     FlagSpec = FlagSpec { name: "--error-format-human", value_name: "VALUE", possible: Some(ERROR_FORMAT_HUMAN) };
const F_DIAGW:    FlagSpec = FlagSpec { name: "--diagnostic-width", value_name: "WIDTH", possible: None };
const F_Z:        FlagSpec = FlagSpec { name: "-Z", value_name: "FLAG", possible: None };

pub fn parse(prog: &str, args: &[String]) -> Result<ParseOutcome, CliError> {
    let mut opts = Options::new();
    let mut i = 0;
    let mut no_more_flags = false;

    while i < args.len() {
        let a = &args[i];

        if no_more_flags {
            opts.inputs.push(a.clone());
            i += 1;
            continue;
        }

        if a == "--" { no_more_flags = true; i += 1; continue; }

        if a == "--help" { return Ok(ParseOutcome::Help(help::long_help(prog))); }
        if a == "-h" { return Ok(ParseOutcome::Help(help::short_help(prog))); }
        if a == "--version" { return Ok(ParseOutcome::Version(help::long_version().to_string())); }
        if a == "-V" { return Ok(ParseOutcome::Version(help::short_version().to_string())); }

        // -Z handling
        if a == "-Z" {
            let val = args.get(i + 1).cloned().ok_or_else(|| {
                CliError::Parse(F_Z.missing_value_error())
            })?;
            i += 2;
            handle_z(&val, &mut opts)?;
            continue;
        }
        if let Some(rest) = a.strip_prefix("-Z") {
            i += 1;
            handle_z(rest, &mut opts)?;
            continue;
        }

        // Known flags with values.
        if let Some(val) = take_value(a, args, &mut i, "-j", "--threads", &F_THREADS)?
            .or_else(|| take_value(a, args, &mut i, "", "--jobs", &F_THREADS).ok().flatten())
        {
            match val.parse::<usize>() {
                Ok(n) => opts.threads = if n == 0 { num_cpus() } else { n },
                Err(e) => return Err(CliError::Parse(F_THREADS.invalid_value_error(&val, Some(&e.to_string())))),
            }
            continue;
        }
        if let Some(val) = take_value(a, args, &mut i, "", "--evm-version", &F_EVM)? {
            if !EVM_VERSIONS.contains(&val.as_str()) {
