/// Parses a type string and returns the (input_types, output_type) tuple
/// for the corresponding public getter function.
///
/// * For scalars: `() -> T`
/// * For fixed/dynamic arrays: `(uint256) -> T`
/// * For mappings: `(K) -> V` (recursively unpacking nested mappings)
pub fn compute(ty: &str) -> (Vec<String>, String) {
