        let (mut inputs, output) = compute(rest);
        inputs.insert(0, "uint256".into());
        return (inputs, output);
    }
    if let Some((k, v)) = strip_mapping(t) {
        let (mut inputs, output) = compute(&v);
        inputs.insert(0, canonical_mapping_key(&k));
        return (inputs, output);
    }
    (vec![], t.to_string())
}

fn strip_array_suffix(ty: &str) -> Option<&str> {
    let b = ty.as_bytes();
    if !b.ends_with(b"]") { return None; }
    // find matching `[`
    let mut depth = 0i32;
    for i in (0..b.len()).rev() {
        match b[i] {
            b']' => depth += 1,
            b'[' => {
