    let rest = t.strip_prefix("mapping")?;
    let rest = rest.trim_start();
    let rest = rest.strip_prefix('(')?;
    let rest = rest.strip_suffix(')')?;
    // Split on top-level `=>` (arrow)
    let bytes = rest.as_bytes();
    let mut depth = 0i32;
    let mut i = 0;
    while i + 1 < bytes.len() {
        match bytes[i] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            b'=' if depth == 0 && bytes[i + 1] == b'>' => {
                let k = rest[..i].trim().to_string();
                let v = rest[i + 2..].trim().to_string();
                return Some((k, v));
            }
